const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 inches
pres.author = 'WorkspaceX';
pres.title = '团队协作：打造高效协同团队';

// Color palette
const C = {
  primary: '1B3A5C',    // deep navy
  accent: '2E86DE',     // bright blue
  light: 'EBF5FB',      // light blue bg
  white: 'FFFFFF',
  dark: '2C3E50',       // dark text
  gray: '7F8C8D',       // subtitle / caption
  orange: 'E67E22',     // highlight accent
  green: '27AE60',      // success / positive
};

const FONT = '微软雅黑';

// ─── Helper functions ───
function addFooter(slide, pageNum) {
  slide.addText(`${pageNum} / 5`, {
    x: 12.0, y: 7.0, w: 1.0, h: 0.35,
    fontSize: 10, color: C.gray, fontFace: FONT, align: 'right'
  });
  // thin accent line at bottom
  slide.addShape(pres.ShapeType.rect, {
    x: 0, y: 7.25, w: 13.33, h: 0.04, fill: { color: C.accent }
  });
}

function addSectionTitle(slide, title) {
  slide.addShape(pres.ShapeType.rect, {
    x: 0, y: 0, w: 13.33, h: 1.1, fill: { color: C.primary }
  });
  slide.addText(title, {
    x: 0.6, y: 0.15, w: 12.0, h: 0.8,
    fontSize: 28, bold: true, color: C.white, fontFace: FONT
  });
}

// ════════════════════════════════════════
// Slide 1 — Title Page
// ════════════════════════════════════════
{
  const s = pres.addSlide();
  // Full background
  s.addShape(pres.ShapeType.rect, {
    x: 0, y: 0, w: 13.33, h: 7.5, fill: { color: C.primary }
  });
  // Decorative accent bar
  s.addShape(pres.ShapeType.rect, {
    x: 0.8, y: 2.4, w: 0.12, h: 2.6, fill: { color: C.orange }
  });
  // Main title
  s.addText('团队协作', {
    x: 1.3, y: 2.3, w: 10.0, h: 1.2,
    fontSize: 48, bold: true, color: C.white, fontFace: FONT
  });
  // Subtitle
  s.addText('打造高效协同团队的实践与方法', {
    x: 1.3, y: 3.5, w: 10.0, h: 0.8,
    fontSize: 24, color: C.light, fontFace: FONT
  });
  // Divider line
  s.addShape(pres.ShapeType.rect, {
    x: 1.3, y: 4.5, w: 4.0, h: 0.04, fill: { color: C.accent }
  });
  // Presenter info
  s.addText('2024 · 团队管理系列', {
    x: 1.3, y: 4.8, w: 6.0, h: 0.5,
    fontSize: 16, color: C.gray, fontFace: FONT
  });
}

// ════════════════════════════════════════
// Slide 2 — Why Team Collaboration Matters
// ════════════════════════════════════════
{
  const s = pres.addSlide();
  addSectionTitle(s, '为什么团队协作至关重要？');
  addFooter(s, 2);

  const items = [
    { icon: '🚀', title: '提升效率', desc: '合理分工让每个人聚焦擅长领域，整体产出远超个人之和' },
    { icon: '💡', title: '激发创新', desc: '多元视角碰撞产生新想法，跨职能协作打破思维定式' },
    { icon: '🛡️', title: '降低风险', desc: '信息透明与交叉验证减少盲区，问题更早被发现和解决' },
    { icon: '❤️', title: '增强归属感', desc: '共同目标与互相支持建立信任，提升团队凝聚力与留存率' },
  ];

  items.forEach((item, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = 0.6 + col * 6.2;
    const y = 1.5 + row * 2.7;

    // Card background
    s.addShape(pres.ShapeType.roundRect, {
      x, y, w: 5.8, h: 2.3, rectRadius: 0.15,
      fill: { color: C.light }, line: { color: C.accent, width: 0.5 }
    });
    // Icon circle
    s.addShape(pres.ShapeType.ellipse, {
      x: x + 0.3, y: y + 0.35, w: 0.9, h: 0.9,
      fill: { color: C.accent }
    });
    s.addText(item.icon, {
      x: x + 0.3, y: y + 0.35, w: 0.9, h: 0.9,
      fontSize: 28, align: 'center', valign: 'middle', fontFace: FONT
    });
    // Title
    s.addText(item.title, {
      x: x + 1.5, y: y + 0.3, w: 3.8, h: 0.5,
      fontSize: 20, bold: true, color: C.dark, fontFace: FONT
    });
    // Description
    s.addText(item.desc, {
      x: x + 1.5, y: y + 0.9, w: 3.8, h: 1.1,
      fontSize: 14, color: C.dark, fontFace: FONT, lineSpacingMultiple: 1.3
    });
  });
}

// ════════════════════════════════════════
// Slide 3 — Core Principles
// ════════════════════════════════════════
{
  const s = pres.addSlide();
  addSectionTitle(s, '高效协作的四大核心原则');
  addFooter(s, 3);

  const principles = [
    { num: '01', title: '目标对齐', body: '确保每位成员理解并认同\n团队的共同目标与优先级', color: C.accent },
